  ar: { like: 'إعجاب', comment: 'تعليق', follow: 'متابعة', full: 'القصة كاملة ← pressing90.live', weekly: 'قصة جديدة كل يوم', cta: '➕ تابع Pressing 90 لمزيد من قصص كرة القدم المذهلة.', more: '📖 القصة كاملة' },
